class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        char_substrings = defaultdict(list)

        n = len(s)
        for i in range(n):
            if i > 0 and s[i] == s[i-1]:
                continue
            current_char = s[i]
            length = 1
            char_substrings[current_char].append(length)
            for j in range(i+1, n):
                if s[j] == current_char:
                    length += 1
                    char_substrings[current_char].append(length)
                else:
                    break

        max_len = -1
        for char in char_substrings:
            lengths = char_substrings[char]
            lengths.sort(reverse=True)
            count = 1
            for i in range(1, len(lengths)):
                if lengths[i] == lengths[i-1]:
                    count += 1
                    if count >= 3 and lengths[i] > max_len:
                        max_len = lengths[i]
                else:
                    count = 1
            if len(lengths) >= 3 and lengths[0] > max_len:
                if lengths[0] == lengths[1] == lengths[2]:
                    max_len = lengths[0]
                elif lengths[0] == lengths[1] and lengths[0] > max_len:
                    if lengths.count(lengths[0]) >= 3:
                        max_len = lengths[0]
                    else:
                        if lengths[1] == lengths[2] and lengths[1] > max_len:
                            max_len = lengths[1]

        return max_len
